/**
 * POST /api/buyer/orders/[orderId]/payment-plan
 *
 * Body: { planId: uuid }
 *
 * Připojí payment plan k existující objednávce ve status='pending'.
 * Spočítá splátky, vytvoří `order_payment_plans` + `payment_installments`.
 * Buyer pak zaplatí "deposit" přes mock-gopay → order status = 'paid_partial',
 * další splátky čeká cron.
 */

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db/rls-pool';
import { runAsUser } from '@/lib/auth';
import { z } from 'zod';
import { launchFeatureNotFound } from '@/lib/features/launch-flags';


const schema = z.object({
  planId: z.string().uuid(),
});

interface OrderRow {
  id: string;
  user_id: string;
  event_id: string;
  total_amount: number;
  currency: string;
  status: string;
}

interface PlanRow {
  id: string;
  event_id: string | null;
  deposit_pct: number;
  installments_count: number;
  interval_days: number;
  active: boolean;
}

export async function POST(
  req: NextRequest,
  { params }: { params: { orderId: string } },
): Promise<Response> {
  // Kolo 10: vypnuto přepínačem (výchozí stav) → 404.
  const featureOff = launchFeatureNotFound('installments');
  if (featureOff) return featureOff;
  return runAsUser(req, async (userId) => {
  const body: unknown = await req.json().catch(() => ({}));
  const parsed = schema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json(
      { error: 'Validation failed', issues: parsed.error.issues },
      { status: 422 },
    );
  }

  const client = await db().connect();
  try {
    await client.query('BEGIN');
    const ord = await client.query<OrderRow>(
      `SELECT id, user_id, event_id, total_amount, currency, status
       FROM orders.orders
       WHERE id = $1 AND user_id = $2
       FOR UPDATE`,
      [params.orderId, userId],
    );
    if (ord.rows.length === 0) {
      await client.query('ROLLBACK');
      return NextResponse.json({ error: 'Not found' }, { status: 404 });
    }
    const order = ord.rows[0];
    if (order.status !== 'pending') {
      await client.query('ROLLBACK');
      return NextResponse.json(
        { error: 'INVALID_STATE', message: `Order is "${order.status}", plan can only be attached to pending.` },
        { status: 409 },
      );
    }

    const exists = await client.query(
      `SELECT 1 FROM orders.order_payment_plans WHERE order_id = $1`,
      [order.id],
    );
    if (exists.rows.length > 0) {
      await client.query('ROLLBACK');
      return NextResponse.json({ error: 'PLAN_ALREADY_ATTACHED' }, { status: 409 });
    }

    const plan = await client.query<PlanRow>(
      `SELECT id, event_id, deposit_pct, installments_count, interval_days, active
       FROM catalog.payment_plans
       WHERE id = $1`,
      [parsed.data.planId],
    );
    if (plan.rows.length === 0 || !plan.rows[0].active) {
      await client.query('ROLLBACK');
      return NextResponse.json({ error: 'PLAN_NOT_FOUND' }, { status: 404 });
    }
    const p = plan.rows[0];
    if (p.event_id !== order.event_id) {
      await client.query('ROLLBACK');
      return NextResponse.json({ error: 'PLAN_NOT_FOR_EVENT' }, { status: 422 });
    }

    const total = order.total_amount;
    const depositAmount = Math.floor((total * p.deposit_pct) / 100);
    const remaining = total - depositAmount;
    const installmentsCount = p.installments_count;

    const oppRes = await client.query<{ id: string }>(
      `INSERT INTO orders.order_payment_plans
         (order_id, plan_id, total_amount, currency, deposit_amount, status)
       VALUES ($1, $2, $3, $4, $5, 'active')
       RETURNING id`,
      [order.id, p.id, total, order.currency, depositAmount],
    );
    const oppId = oppRes.rows[0].id;

    if (installmentsCount > 0) {
      // Equal-split (last absorbs remainder)
      const baseAmount = Math.floor(remaining / installmentsCount);
      const lastAmount = remaining - baseAmount * (installmentsCount - 1);
      const now = Date.now();
      for (let i = 1; i <= installmentsCount; i++) {
        const amount = i === installmentsCount ? lastAmount : baseAmount;
        const dueAt = new Date(now + p.interval_days * i * 24 * 60 * 60 * 1000);
        await client.query(
          `INSERT INTO orders.payment_installments
             (order_payment_plan_id, sequence, amount, due_at, status)
           VALUES ($1, $2, $3, $4, 'pending')`,
          [oppId, i, amount, dueAt.toISOString()],
        );
      }
    }

    await client.query('COMMIT');
    return NextResponse.json({
      ok: true,
      orderPaymentPlanId: oppId,
      depositAmount,
      installmentsCount,
      remainingAmount: remaining,
    });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('[attach payment plan]', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  } finally {
    client.release();
  }

  });
}

/**
 * POST /api/internal/cron/charge-installments
 *
 * Cron — charge due instalments (mock):
 *   - Najde `payment_installments` ve status='pending' s due_at <= NOW()
 *   - V demu auto-success → status='paid', charged_at=NOW()
 *   - V produkci: Stripe paymentIntent.create, fail → retry up to 3x, pak status='failed'
 *   - Pokud všechny instalments paid → order_payment_plans.status='completed' + order.status='paid'
 *
 * Auth: x-internal-token.
 */

import { timingSafeEqual } from 'crypto';
import { db, runWithServiceContext } from '@/lib/db/rls-pool';
import { NextRequest, NextResponse } from 'next/server';
import { launchFeatureNotFound } from '@/lib/features/launch-flags';


function safeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(a, 'utf8');
  const bb = Buffer.from(b, 'utf8');
  if (ab.length !== bb.length) return false;
  return timingSafeEqual(ab, bb);
}

export async function POST(req: NextRequest): Promise<Response> {
  // Kolo 10: vypnuto přepínačem (výchozí stav) → 404.
  const featureOff = launchFeatureNotFound('installments');
  if (featureOff) return featureOff;
  return runWithServiceContext(async () => {

  const token = req.headers.get('x-internal-token') ?? '';
  const expected = process.env.INTERNAL_SERVICE_TOKEN ?? '';
  if (!expected || !safeEqual(token, expected)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  const due = await db().query<{
    id: string;
    order_payment_plan_id: string;
    sequence: number;
    amount: number;
    retry_count: number;
  }>(
    `SELECT id, order_payment_plan_id, sequence, amount, retry_count
     FROM orders.payment_installments
     WHERE status = 'pending' AND due_at <= NOW()
     ORDER BY due_at ASC
     LIMIT 500`,
  );

  let paid = 0;
  let failed = 0;
  let completedPlans = 0;

  for (const inst of due.rows) {
    const client = await db().connect();
    try {
      await client.query('BEGIN');

      // Re-check + lock
      const recheck = await client.query<{ status: string }>(
        `SELECT status FROM orders.payment_installments
         WHERE id = $1 FOR UPDATE`,
        [inst.id],
      );
      if (recheck.rows.length === 0 || recheck.rows[0].status !== 'pending') {
        await client.query('ROLLBACK');
        continue;
      }

      // Real Stripe charge pokud máme Customer + PaymentMethod, jinak mock
      let providerRef = `mock-cron-${inst.id.slice(0, 8)}`;
      const useStripe = Boolean(process.env.STRIPE_SECRET_KEY);

      if (useStripe) {
        const ctx = await client.query<{
          customer_id: string | null;
          payment_method_id: string | null;
          currency: string;
        }>(
          `SELECT u.stripe_customer_id AS customer_id,
                  o.stripe_payment_method_id AS payment_method_id,
                  o.currency
           FROM orders.payment_installments pi
           JOIN orders.order_payment_plans opp ON opp.id = pi.order_payment_plan_id
           JOIN orders.orders o ON o.id = opp.order_id
           JOIN identity.users u ON u.id = o.user_id
           WHERE pi.id = $1`,
          [inst.id],
        );
        const row = ctx.rows[0];
        if (row?.customer_id && row?.payment_method_id) {
          const { chargeSavedPaymentMethod } = await import('@/lib/payment/stripe');
          const result = await chargeSavedPaymentMethod({
            customerId: row.customer_id,
            paymentMethodId: row.payment_method_id,
            amountHalire: inst.amount,
            currency: row.currency,
            description: `Splatka ${inst.sequence} (instalment ${inst.id.slice(0, 8)})`,
            idempotencyKey: `inst-${inst.id}`,
          });
          if (result.ok) {
            providerRef = result.paymentIntentId;
          } else {
            await client.query(
              `UPDATE orders.payment_installments
               SET retry_count = retry_count + 1,
                   last_attempt_at = NOW(),
                   last_error = $2,
                   status = CASE WHEN retry_count >= 2 THEN 'failed' ELSE 'pending' END,
                   grace_period_ends_at = CASE
                     WHEN retry_count >= 2 THEN NULL
                     ELSE NOW() + INTERVAL '3 days'
                   END
               WHERE id = $1`,
              [inst.id, result.reason.slice(0, 500)],
            );
            await client.query('COMMIT');
            failed += 1;
            continue;
          }
        }
        // Pokud chybí customer_id/payment_method_id, fallback na mock charge
      }

      await client.query(
        `UPDATE orders.payment_installments
         SET status = 'paid', charged_at = NOW(),
             payment_provider_ref = $2,
             last_error = NULL
         WHERE id = $1`,
        [inst.id, providerRef],
      );
      paid += 1;

      // Last one? → mark plan completed + order paid
      const remaining = await client.query<{ count: string }>(
        `SELECT COUNT(*)::text AS count FROM orders.payment_installments
         WHERE order_payment_plan_id = $1 AND status != 'paid'`,
        [inst.order_payment_plan_id],
      );
      if (Number(remaining.rows[0]?.count ?? 0) === 0) {
        const opp = await client.query<{ order_id: string }>(
          `UPDATE orders.order_payment_plans
           SET status = 'completed', completed_at = NOW()
           WHERE id = $1
           RETURNING order_id`,
          [inst.order_payment_plan_id],
        );
        if (opp.rows.length > 0) {
          await client.query(
            `UPDATE orders.orders SET status = 'paid', paid_at = NOW(), updated_at = NOW()
             WHERE id = $1 AND status IN ('paid_partial', 'pending')`,
            [opp.rows[0].order_id],
          );
          completedPlans += 1;
        }
      }

      await client.query('COMMIT');
    } catch (err) {
      await client.query('ROLLBACK');
      console.error('[charge-installments]', inst.id, err);
      failed += 1;
      try {
        await db().query(
          `UPDATE orders.payment_installments
           SET retry_count = retry_count + 1,
               status = CASE WHEN retry_count >= 2 THEN 'failed' ELSE 'pending' END
           WHERE id = $1`,
          [inst.id],
        );
      } catch {
        // ignore
      }
    } finally {
      client.release();
    }
  }

  return NextResponse.json({      // R-46: driv `ok: true` natvrdo, i kdyz `failed > 0`. Audit C2 sel po
      // jmennem seznamu devíti rout, takze tahle proklouzla (FINDINGS 174).

    ok: failed === 0,
    processed: due.rows.length,
    paid,
    failed,
    completedPlans,
  });

  });
}

/**
 * POST /api/internal/cron/payouts-execute
 *
 * Execution step after payouts-auto-settle.
 * Picks up all 'pending' payout records and sends the money via:
 *   - Wise: SEPA Credit Transfer / SWIFT (EU/international)
 *   - PayPal Payouts: if promoter.payout_method = 'paypal'
 *   - FIO manual note: CZK domestic (operator initiates from FIO internet banking)
 *
 * Plánování (kolo 10): pro první ostrý provoz NENÍ naplánováno (není ve vercel.json ani v ALLOWED_JOBS dispatcheru).
 * Výplaty jsou ruční: platform admin je spouští v administraci (/api/admin/payouts/execute) a u CZK/FIO převod
 * odešle z internetového bankovnictví; výplata čeká ve stavu awaiting_manual_transfer, dokud ji admin nepotvrdí
 * (/api/platform/admin/payouts/[id]/confirm-transfer). Test: tests/fix-r10-launch-flags.test.ts (crony).
 *
 * Security: x-internal-token header required.
 *
 * Idempotent: uses external_payout_id + payout UUID as idempotency keys.
 * Safe to re-run — already paid payouts are skipped (status != 'pending').
 *
 * Max batch: 50 payouts per run (rate limits on Wise/PayPal). Scheduled cron
 * runs daily so backlog clears within days.
 */

import { NextRequest, NextResponse } from 'next/server';
import { timingSafeEqual } from 'crypto';
import { fetchPendingPayouts, executePayout } from '@/lib/payouts/executor';

export const dynamic = 'force-dynamic';

function safeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(a, 'utf8');
  const bb = Buffer.from(b, 'utf8');
  if (ab.length !== bb.length) return false;
  return timingSafeEqual(ab, bb);
}

export async function POST(req: NextRequest): Promise<Response> {
  const token = req.headers.get('x-internal-token') ?? '';
  const expected = process.env.INTERNAL_SERVICE_TOKEN ?? '';
  if (!expected || !safeEqual(token, expected)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  const batchSize = Number(new URL(req.url).searchParams.get('limit') ?? '50');
  const pending = await fetchPendingPayouts(Math.min(batchSize, 100));

  if (pending.length === 0) {
    return NextResponse.json({ ok: true, processed: 0, failed: 0, errors: [], message: 'No pending payouts' });
  }

  const results = await Promise.allSettled(pending.map((row) => executePayout(row)));

  // Kolo 7 (C-57): executor už nehlásí 'paid' — Wise čeká na webhook, CZK na ruční převod.
  let processing = 0;
  let awaitingManualTransfer = 0;
  let skipped = 0;
  let failed = 0;
  const errors: string[] = [];

  for (const result of results) {
    if (result.status === 'fulfilled') {
      if (result.value.status === 'processing') processing++;
      else if (result.value.status === 'awaiting_manual_transfer') awaitingManualTransfer++;
      else if (result.value.status === 'skipped') skipped++;
      else {
        failed++;
        if (result.value.reason) errors.push(`${result.value.payoutId}: ${result.value.reason}`);
      }
    } else {
      failed++;
      errors.push(String(result.reason));
    }
  }

  console.info(`[payouts-execute] batch=${pending.length} processing=${processing} awaitingManualTransfer=${awaitingManualTransfer} skipped=${skipped} failed=${failed}`);

  return NextResponse.json({
    // R-46: driv `ok: true` natvrdo vedle neprazdneho `errors`. U vyplat to
    // znamenalo, ze selhani jednotlivych plateb hlasil cron jako uspech.
    ok: errors.length === 0 && failed === 0,
    processed: pending.length,
    processing,
    awaitingManualTransfer,
    skipped,
    failed,
    errors,
  });
}

/**
 * POST /api/internal/cron/renew-subscriptions
 *
 * Cron — projde subscriptions s next_billing_at <= NOW() a:
 *   - posune current_period_start/end + next_billing_at
 *   - V produkci: charge přes Stripe; pokud fail → status='past_due'.
 *   - V demu: instant renew (mock GoPay).
 *
 * Auth: x-internal-token.
 */

import { timingSafeEqual } from 'crypto';
import { db, runWithServiceContext } from '@/lib/db/rls-pool';
import { NextRequest, NextResponse } from 'next/server';
import { launchFeatureNotFound } from '@/lib/features/launch-flags';


function safeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(a, 'utf8');
  const bb = Buffer.from(b, 'utf8');
  if (ab.length !== bb.length) return false;
  return timingSafeEqual(ab, bb);
}

export async function POST(req: NextRequest): Promise<Response> {
  // Kolo 10: vypnuto přepínačem (výchozí stav) → 404.
  const featureOff = launchFeatureNotFound('subscriptions');
  if (featureOff) return featureOff;
  return runWithServiceContext(async () => {

  const token = req.headers.get('x-internal-token') ?? '';
  const expected = process.env.INTERNAL_SERVICE_TOKEN ?? '';
  if (!expected || !safeEqual(token, expected)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  // Find due subscriptions
  const due = await db().query<{
    id: string;
    plan_id: string;
    billing_cycle: string;
    cancel_at_period_end: boolean;
  }>(
    `SELECT s.id, s.plan_id, p.billing_cycle, s.cancel_at_period_end
     FROM subscriptions.subscriptions s
     JOIN subscriptions.plans p ON p.id = s.plan_id
     WHERE s.status = 'active'
       AND s.next_billing_at <= NOW()`,
  );

  let renewed = 0;
  let cancelled = 0;
  for (const sub of due.rows) {
    if (sub.cancel_at_period_end) {
      await db().query(
        `UPDATE subscriptions.subscriptions
         SET status = 'cancelled', cancelled_at = NOW()
         WHERE id = $1`,
        [sub.id],
      );
      cancelled += 1;
      continue;
    }
    // NOTE (ForgeMsg): production billing will charge via Stripe here; on a
    // failed charge set status='past_due' and emit the dunning trigger:
    //   await emitForgeMsg({ type: 'subscription_past_due',
    //     contact: { email: <buyer email> },
    //     payload: { renew_url, subscription_id: sub.id } }, <promoter_id>);
    // Not wired today because this cron is a mock instant-renew (no past_due path).
    // Mock renew: posuneme period
    const advanceClause =
      sub.billing_cycle === 'monthly'
        ? `NOW() + INTERVAL '1 month'`
        : `NOW() + INTERVAL '1 year'`;
    await db().query(
      `UPDATE subscriptions.subscriptions
       SET current_period_start = NOW(),
           current_period_end = ${advanceClause},
           next_billing_at = ${advanceClause}
       WHERE id = $1`,
      [sub.id],
    );
    renewed += 1;
  }

  return NextResponse.json({ ok: true, processed: due.rows.length, renewed, cancelled });

  });
}

