import { jwtVerify } from 'jose';
import { isAccessTokenPayload } from '@/lib/security/token-type';
import { hasAuthCookie, isCsrfExemptPath, isSameOriginRequest, isStateChangingMethod } from '@/lib/security/csrf';
import { NextRequest, NextResponse } from 'next/server';
import {
  detectLocale,
  getPathnameLocale,
  pathnameWithoutLocale,
  LOCALE_COOKIE,
} from '@/lib/i18n';

// ── JWT helpers (Edge Runtime — jose only) ───────────────────────────────────

function getSecret(): Uint8Array {
  const secret = process.env.JWT_SECRET;
  if (!secret || secret.length < 32) {
    throw new Error('JWT_SECRET missing or too short');
  }
  return new TextEncoder().encode(secret);
}

interface JWTRoles {
  isPlatformAdmin?: boolean;
  promoterMemberships?: Array<{ promoterId: string; status: string; role: string }>;
}

interface AccessPayload {
  sub: string;
  isAdmin: boolean;
  roles: JWTRoles;
}

async function verifyTokenEdge(token: string): Promise<AccessPayload | null> {
  try {
    const { payload } = await jwtVerify(token, getSecret(), { algorithms: ['HS256'] });
    const sub = typeof payload.sub === 'string' ? payload.sub : null;
    if (!sub) return null;
    // FIX K4d: přihlášení jen access tokenem (refresh token stejného klíče se odmítne).
    if (!isAccessTokenPayload(payload)) return null;
    const roles = (payload as { roles?: JWTRoles }).roles ?? {};
    const isAdmin = roles.isPlatformAdmin === true;
    return { sub, isAdmin, roles };
  } catch {
    return null;
  }
}


function jsonResponse(body: object, status: number): NextResponse {
  return new NextResponse(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

// ── Route lists ─────────────────────────────────────────────────────────────

const API_AUTH_PREFIX = '/api/auth/';

const API_PUBLIC_GET_ROUTES = ['/api/events/', '/api/search', '/api/cross-passes/', '/api/subscriptions/plans', '/api/public/'];

// API routes that require auth + admin (platform admin OR promoter membership).
// FIX K1: /api/kiosk/ přidáno — kiosk (pokladní terminál) musí běžet pod přihlášenou
// obsluhou; middleware ověří JWT a injektuje x-user-id, handler pak ověří oprávnění
// k dané akci. Bez tohohle byl kiosk veřejný (vstupenky zdarma bez přihlášení).
const API_PROMOTER_PREFIXES = ['/api/admin/', '/api/orders/', '/api/kiosk/'];
const API_PLATFORM_PREFIXES = ['/api/platform/'];
// Optional auth: token if present propagates as x-user-id, otherwise pass through
// /api/transfer/accept/ je tu (ne v PUBLIC): GET preview funguje bez tokenu,
// ale POST accept potřebuje x-user-id → optional auth ho injektuje, je-li token.
// /api/mobile/, /api/my/ (kolo 3): bez prefixu tady se token nikdy neověřil a routy
// (runAsUser / x-user-id) vracely vždy 401.
const API_OPTIONAL_AUTH_PREFIXES = ['/api/buyer/', '/api/checkout', '/api/subscriptions/', '/api/queue/', '/api/transfer/accept/', '/api/mobile/', '/api/my/'];

// Frontend routes (matched WITHOUT locale prefix)
const FRONTEND_PROMOTER = ['/admin'];
const FRONTEND_PLATFORM = ['/platform'];
const FRONTEND_AUTH_ONLY = ['/login', '/register', '/register-promoter'];

// Public mock-gopay endpoints (skip auth entirely, even in API)
// GET /api/transfer/accept/[token] je public (recipient ještě nepřihlášený);
// POST /api/transfer/accept/[token] vyžaduje x-user-id ale endpoint si to ověří
// sám — middleware ho pustí.
// /api/offers/ — nabídka umělci se otevírá jednorázovým odkazem. Agent u nás
// účet nemá a mít nemusí; oprávnění nese token v odkazu, ověřuje ho endpoint.
const PUBLIC_API_PREFIXES = ['/api/health', '/api/internal/', '/api/mock-gopay', '/api/mock-bnpl/', '/api/team/accept', '/api/lottery/', '/api/gift/', '/api/newsletter/', '/api/support/chat', '/api/group-invitations/', '/api/charity/claim/', '/api/payments/benefit/', '/api/reseller/', '/api/offers/'];

// ── Middleware ──────────────────────────────────────────────────────────────

export async function middleware(request: NextRequest): Promise<NextResponse> {
  const { pathname } = request.nextUrl;

  // Root „/" → /cs (lokalizovaná landing page). `/cs` samotná se RENDERUJE
  // (marketingová landing: hero + kategorie + feed + tipy redakce). Plný výpis
  // akcí má vlastní route /cs/events. Admin/promotér si workspace otevře přes nav.
  if (pathname === '/') {
    return NextResponse.redirect(new URL('/cs', request.url));
  }

  // ── 1. API routes ────────────────────────────────────────────────────────
  if (pathname.startsWith('/api/')) {
    // SECURITY (CRITICAL): identita smí pocházet VÝHRADNĚ z JWT, který níže sami
    // ověříme a injektujeme jako x-user-id / x-is-admin. Jakýkoli stejnojmenný
    // header v PŘÍCHOZÍM requestu je klientem podvržený pokus o impersonaci —
    // proto ho zahodíme na VŠECH cestách (i pass-through / public / optional-auth
    // bez tokenu), DŘÍV než se dostane k handlerům (runAsUser, requirePromoter…),
    // které těmto hlavičkám slepě věří. Bez tohohle stripu stačí poslat
    // `x-user-id: <uuid-oběti>` a číst/měnit cizí data bez jakéhokoli tokenu.
    const requestHeaders = new Headers(request.headers);
    requestHeaders.delete('x-user-id');
    requestHeaders.delete('x-is-admin');
    requestHeaders.delete('x-is-platform-admin');
    // Kolo 2: x-vercel-cron fungovalo jako „systémová role" (cron routy ho braly
    // jako autentizaci) — klient ho podvrhne stejně snadno jako x-user-id.
    requestHeaders.delete('x-vercel-cron');
    // Kolo 4: identita z OVĚŘENÉHO access tokenu se předává u VŠECH /api cest, ne jen
    // u vyjmenovaných prefixů. Dřív cesta mimo seznam prošla bez x-user-id a routy, které
    // identitu potřebují, vracely vždy 401 i přihlášenému (25 rout, FIX_REPORT_R3). Zda je
    // přihlášení povinné, rozhoduje dál prefix níže nebo handler; tady se jen nezahazuje.
    const passThrough = async (): Promise<NextResponse> => {
      const optionalAuthHeader = request.headers.get('Authorization');
      const optionalBearer =
        optionalAuthHeader && optionalAuthHeader.startsWith('Bearer ') ? optionalAuthHeader.split(' ')[1] : null;
      const optionalCookie = request.cookies.get('accessToken')?.value ?? null;
      let optionalPayload = optionalBearer ? await verifyTokenEdge(optionalBearer) : null;
      if (!optionalPayload && optionalCookie && optionalCookie !== optionalBearer) {
        optionalPayload = await verifyTokenEdge(optionalCookie);
      }
      if (optionalPayload) requestHeaders.set('x-user-id', optionalPayload.sub);
      return NextResponse.next({ request: { headers: requestHeaders } });
    };

    // FIX K5 (kolo 3): CSRF — stavový požadavek autentizovaný cookie musí přijít z vlastního
    // webu (Origin, jinak Referer); cizí / chybějící → 403. Výjimky a důvody: lib/security/csrf.ts.
    // Platný Bearer token = API klient (hlavičku cizí stránka bez CORS neposlat neumí) → bez kontroly;
    // neplatný Bearer nic neomlouvá (middleware by spadl zpět na cookie).
    if (isStateChangingMethod(request.method) && !isCsrfExemptPath(pathname) && hasAuthCookie(request)) {
      const authz = request.headers.get('authorization');
      const bearerTok = authz && authz.startsWith('Bearer ') ? authz.slice(7) : null;
      const bearerOk = bearerTok ? (await verifyTokenEdge(bearerTok)) !== null : false;
      if (!bearerOk && !isSameOriginRequest(request)) {
        return jsonResponse({ error: 'CSRF_ORIGIN_MISMATCH', message: 'Požadavek nepochází z tohoto webu.' }, 403);
      }
    }

    if (pathname.startsWith(API_AUTH_PREFIX)) {
      return passThrough();
    }
    if (PUBLIC_API_PREFIXES.some((r) => pathname.startsWith(r))) {
      return passThrough();
    }
    // Kolo 10 / krok 3: Vercel cron volá GET s `Authorization: Bearer CRON_SECRET` (není JWT → tady by dostal 401).
    // Jen tato přesná cesta a jen GET; tajemství cronu ověřuje handler (isCronAuthorized), identita se nepředává.
    if (pathname === '/api/admin/lastminute/check' && request.method === 'GET') {
      return passThrough();
    }

    const isPublicGet =
      API_PUBLIC_GET_ROUTES.some((r) => pathname.startsWith(r)) &&
      request.method === 'GET';
    if (isPublicGet) {
      return passThrough();
    }

    const isPlatformApi = API_PLATFORM_PREFIXES.some((r) => pathname.startsWith(r));
    const isPromoterApi = API_PROMOTER_PREFIXES.some((r) => pathname.startsWith(r));
    const isOptionalAuthApi = API_OPTIONAL_AUTH_PREFIXES.some((r) =>
      pathname.startsWith(r),
    );

    if (!isPlatformApi && !isPromoterApi && !isOptionalAuthApi) {
      return passThrough();
    }

    // Optional auth: token (ověřený) → x-user-id, jinak bez identity — totéž dělá passThrough.
    if (isOptionalAuthApi) {
      return passThrough();
    }

    // Token z Bearer headeru NEBO accessToken cookie. Bearer z localStorage může
    // vypršet dřív, než se obnoví; když je neplatný, spadneme zpět na cookie (kterou
    // prohlížeč posílá sám a obnovuje se při loginu) — jinak by authed fetch hodil 401
    // přestože je relace přes cookie platná.
    const authHeader = request.headers.get('Authorization');
    const bearer =
      authHeader && authHeader.startsWith('Bearer ') ? authHeader.split(' ')[1] : null;
    const cookieToken = request.cookies.get('accessToken')?.value ?? null;

    if (!bearer && !cookieToken) {
      return jsonResponse(
        { error: { code: 'TOKEN_MISSING', message: 'Authorization required' } },
        401,
      );
    }

    let payload = bearer ? await verifyTokenEdge(bearer) : null;
    if (!payload && cookieToken && cookieToken !== bearer) {
      payload = await verifyTokenEdge(cookieToken);
    }
    if (!payload) {
      return jsonResponse(
        { error: { code: 'TOKEN_INVALID', message: 'Token invalid or expired' } },
        401,
      );
    }

    if (isPlatformApi && !payload.roles.isPlatformAdmin) {
      return jsonResponse(
        { error: { code: 'PLATFORM_ADMIN_REQUIRED', message: 'Platform admin access required' } },
        403,
      );
    }
    if (
      isPromoterApi &&
      !payload.roles.isPlatformAdmin &&
      !(payload.roles.promoterMemberships?.length)
    ) {
      return jsonResponse(
        { error: { code: 'PROMOTER_REQUIRED', message: 'Promoter membership required' } },
        403,
      );
    }

    requestHeaders.set('x-user-id', payload.sub);
    requestHeaders.set('x-is-admin', payload.isAdmin ? 'true' : 'false');
    return NextResponse.next({ request: { headers: requestHeaders } });
  }

  // ── 2. Frontend routes ───────────────────────────────────────────────────
  // /admin and /platform are NOT locale-prefixed
  if (
    FRONTEND_PROMOTER.some((r) => pathname === r || pathname.startsWith(r + '/')) ||
    FRONTEND_PLATFORM.some((r) => pathname === r || pathname.startsWith(r + '/'))
  ) {
    const accessToken = request.cookies.get('accessToken')?.value;
    const payload = accessToken ? await verifyTokenEdge(accessToken) : null;
    if (!payload) {
      // accessToken chybí nebo vypršel (15 min TTL). Než vyhodíme na login,
      // zkus tichý refresh přes dlouhodobý refreshToken (7 dní) — promotér tak
      // zůstane přihlášený a nezažije matoucí "jsem přihlášený, ale /admin mě vyhazuje".
      const refreshToken = request.cookies.get('refreshToken')?.value;
      if (refreshToken && (await verifyTokenEdge(refreshToken))) {
        const refreshUrl = new URL('/api/auth/refresh', request.url);
        refreshUrl.searchParams.set('redirect', pathname);
        return NextResponse.redirect(refreshUrl);
      }
      const loginUrl = new URL('/cs/login', request.url);
      loginUrl.searchParams.set('from', pathname);
      return NextResponse.redirect(loginUrl);
    }
    // Čisté oddělení rolí:
    //   /platform = JEN super admin (provozovatel systému)
    //   /admin    = JEN promotér se členstvím (správa svých akcí)
    // Kdo se splete, je přesměrován do SVÉ oblasti (ne do prázdné/rozbité).
    const isPlatform = FRONTEND_PLATFORM.some(
      (r) => pathname === r || pathname.startsWith(r + '/'),
    );
    const isPlatformAdmin = payload.roles.isPlatformAdmin === true;
    const hasPromoter = (payload.roles.promoterMemberships?.length ?? 0) > 0;

    if (isPlatform) {
      if (!isPlatformAdmin) {
        // promotér (bez super admin) → jeho /admin; kupující → veřejné akce
        return NextResponse.redirect(new URL(hasPromoter ? '/admin' : '/cs/events', request.url));
      }
    } else {
      // /admin
      if (!hasPromoter) {
        // čistý super admin → jeho /platform; kupující → veřejné akce
        return NextResponse.redirect(new URL(isPlatformAdmin ? '/platform' : '/cs/events', request.url));
      }
    }
    return NextResponse.next();
  }

  // Mock payment gateway pages live outside the [locale] segment
  // (src/app/mock-gopay/, /mock-wero/, /mock-przelewy24/, /mock-benefit/).
  // Locale prefix would redirect to /cs/mock-X/Y — which has no matching
  // route file and 404s. Pass through unchanged.
  if (
    pathname.startsWith('/mock-gopay/') ||
    pathname.startsWith('/mock-wero/') ||
    pathname.startsWith('/mock-przelewy24/') ||
    pathname.startsWith('/mock-benefit/') ||
    pathname.startsWith('/mock-subscription/') ||
    pathname.startsWith('/mock-voucher/') ||
    pathname.startsWith('/mock-bnpl/') ||
    pathname.startsWith('/r/') ||
    // Embed widgety (src/app/embed/) a mobilní lístek (src/app/m/) žijí MIMO [locale]
    // segment a mají vlastní layout. Locale prefix by je přesměroval na /cs/embed/…
    // resp. /cs/m/… které neexistují → 404 (rozbitý iframe na cizím webu / mobilní lístek).
    pathname.startsWith('/embed/') ||
    pathname.startsWith('/m/') ||
    pathname.startsWith('/reseller/') ||
    // Nabídka umělci — agent ji otevírá odkazem, bez účtu a bez volby jazyka.
    pathname.startsWith('/nabidka/') ||
    // Kiosk — samoobslužný terminál (bez locale prefix, bez auth)
    pathname.startsWith('/kiosk/')
  ) {
    return NextResponse.next();
  }

  // PWA assets — manifest, service worker, icons, offline fallback page.
  // Tyto musí být dostupné bez locale prefix (browser/PWA spec).
  if (
    pathname === '/manifest.json' ||
    pathname === '/sw.js' ||
    pathname === '/offline' ||
    /^\/icon-\d+\.png$/.test(pathname)
  ) {
    return NextResponse.next();
  }

  // Locale handling for the rest of the frontend
  const currentLocale = getPathnameLocale(pathname);

  if (!currentLocale) {
    const cookieLocale = request.cookies.get(LOCALE_COOKIE)?.value ?? null;
    const acceptLanguage = request.headers.get('accept-language');
    const locale = detectLocale(acceptLanguage, cookieLocale);

    const url = request.nextUrl.clone();
    url.pathname = `/${locale}${pathname}`;

    const response = NextResponse.redirect(url);
    response.cookies.set(LOCALE_COOKIE, locale, {
      maxAge: 60 * 60 * 24 * 365,
      sameSite: 'lax',
      httpOnly: false,
    });
    return response;
  }

  const pathWithoutLocale = pathnameWithoutLocale(pathname);
  const accessToken = request.cookies.get('accessToken')?.value;

  // Auth-only pages (login/register) když už přihlášený → veřejný marketplace.
  // Admin přejde do /platform manuálně přes nav link, ne magic redirectem z login URL.
  if (FRONTEND_AUTH_ONLY.some((r) => pathWithoutLocale.startsWith(r)) && accessToken) {
    return NextResponse.redirect(new URL(`/${currentLocale}/events`, request.url));
  }

  const response = NextResponse.next();
  response.headers.set('x-locale', currentLocale);
  return response;
}

export const config = {
  matcher: [
    // Exclude Next.js internals + static assets v /public co se servují přímo.
    // embed.js, sw.js a manifest.json MUSÍ být accessible bez locale prefix
    // (3rd party embeds + service worker registrations).
    // pdf.worker.min.mjs = pdfjs worker (seating editor) — same-origin z /public;
    // bez výjimky by locale middleware udělal 307 → /cs/pdf.worker.min.mjs → 404.
    '/((?!_next/static|_next/image|favicon\\.ico|robots\\.txt|sitemap\\.xml|embed\\.js|sw\\.js|manifest\\.json|pdf\\.worker\\.min\\.mjs|icons/).*)',
  ],
};
